!function(){"use strict";function articuloFraccionableCtrl($scope,mS,modalSvc,nombreModalInventario,tS){$scope.datSearch={pageIndex:1,pageSize:10},$scope.openModal=async function(item){try{const{fileCtrl:fileCtrl,controller:controller,template:template}=nombreModalInventario.ARTICULO_FRACCIONADO;let ctrl=(await import(fileCtrl))[controller];const modalRef=modalSvc.openModalCustom({controller:ctrl,template:template,size:"xl",params:item});modalRef.result.then(res=>{"object"==typeof res&&$scope.getAllArticuloFraccionado()})}catch(error){console.log(error)}},$scope.getAllArticuloFraccionado=function(){try{$scope.articuloFraccionados=[],showLoader(),mS.getData("get","/ArticuloFraccionado/Get?json="+JSON.stringify($scope.dataSearch)).then(response=>{hideLoader(),"0"==response.code&&console.log(response),"1"===response.code&&($scope.articuloFraccionados=JSON.parse(response.payload)||[],hideLoader())}).catch(error=>{hideLoader(),console.log(error)})}catch(error){console.log(error)}},$scope.getAllArticuloFraccionado(),$scope.askToDelete=async function(item){try{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar este registro ahora</small>",confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1});isConfirmed&&mS.getData("delete","/ArticuloFraccionado/Delete?id="+item.idArticuloFraccionado).then(response=>{"0"==response.id&&tS.toastr("warning",response.message),"1"==response.id&&(tS.toastr("success",response.message),$scope.getAllArticuloFraccionado())})}catch(error){console.log(error)}}}app.controller("articuloFraccionableCtrl",articuloFraccionableCtrl),articuloFraccionableCtrl.$inject=["$scope","mainService","modalService","nombreModalInventario","toastService"]}(window.angular);